SELECT m.chembl_id AS chembl_id, m.pref_name, cs.canonical_smiles, m.max_phase, dm.mechanism_of_action, dm.action_type, td.chembl_id AS target_chembl_id, td.pref_name AS target_name FROM molecule_dictionary m LEFT JOIN compound_structures cs ON m.molregno = cs.molregno JOIN drug_mechanism dm ON m.molregno = dm.molregno JOIN target_dictionary td ON dm.tid = td.tid WHERE dm.action_type = 'BLOCKER'
